from jsonb_to_recordset($json$[{"id":"che-so-251","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Berkeley and Hartley devised a laboratory method to measure","options":["osmotic pressure","$K_H$","mass percent","electron spin"],"answer_index":0,"explanation":"Their apparatus applies a measured pressure to just stop osmosis.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-252","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"At constant temperature, osmotic pressure of a dilute non-electrolyte is proportional to","options":["the molar concentration","the square of the concentration","1/C","the solvent $K_b$"],"answer_index":0,"explanation":"$\\pi = CRT$ at fixed T is a direct proportion between $\\pi$ and C.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-253","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A 0.10 M non-electrolyte at 300 K (R = 0.0821 L atm K⁻¹ mol⁻¹) has $\\pi$ nearest","options":["2.46 atm","0.082 atm","3.00 atm","24.6 atm"],"answer_index":0,"explanation":"$\\pi = 0.10 \\times 0.0821 \\times 300 = 2.46$ atm.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-254","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Glucose 18 g (180 g mol⁻¹) in 1.0 L at 27 °C (R = 0.0821 L atm K⁻¹ mol⁻¹) shows $\\pi$ of","options":["2.46 atm","0.82 atm","18 atm","0.10 atm"],"answer_index":0,"explanation":"C = 0.10 mol L⁻¹, T = 300 K, so $\\pi = 0.10 \\times 0.0821 \\times 300 = 2.46$ atm.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-255","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Human blood is approximately isotonic with","options":["0.91% (w/v) NaCl","10% NaCl","pure water","5 M urea"],"answer_index":0,"explanation":"Physiological saline (~0.91% NaCl, about 0.16 M) matches the osmotic pressure of blood.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-256","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A 2.0 g sample of a polymer in 1.0 L of solution at 300 K shows $\\pi = 4.1 \\times 10^{-4}$ atm (R = 0.082 L atm K⁻¹ mol⁻¹). Molar mass is nearest","options":["1.2 × 10⁵ g mol⁻¹","1.2 × 10³ g mol⁻¹","2.0 × 10⁴ g mol⁻¹","8.2 × 10² g mol⁻¹"],"answer_index":0,"explanation":"C = $\\pi / RT$ = 4.1 × 10⁻⁴ / (0.082 × 300) = 1.67 × 10⁻⁵ mol L⁻¹; M = 2.0 / 1.67 × 10⁻⁵ ≈ 1.2 × 10⁵.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-257","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Red blood cells swell and may burst when placed in","options":["pure water, which is hypotonic","0.91% saline","concentrated brine","absolute ethanol"],"answer_index":0,"explanation":"Water rushes in because $\\pi$ outside is far smaller than $\\pi$ of the cytoplasm (haemolysis).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-258","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"At 273 K a solution with C = 0.50 mol L⁻¹ (R = 0.0821 L atm K⁻¹ mol⁻¹) has osmotic pressure nearest","options":["11.2 atm","0.50 atm","22.4 atm","1.00 atm"],"answer_index":0,"explanation":"$\\pi = 0.50 \\times 0.0821 \\times 273 \\approx 11.2$ atm.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-259","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Urea 3.0 g (60 g mol⁻¹) occupies 250 mL of solution at 27 °C. Using R = 0.0821 L atm K⁻¹ mol⁻¹, $\\pi$ is nearest","options":["4.9 atm","2.5 atm","0.82 atm","12 atm"],"answer_index":0,"explanation":"C = 0.050 / 0.250 = 0.20 M; T = 300 K; $\\pi = 0.20 \\times 0.0821 \\times 300 \\approx 4.9$ atm.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-260","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"An aqueous NaCl solution that is 0.10 M and fully ionised (i = 2) at 300 K (R = 0.0821 L atm K⁻¹ mol⁻¹) has $\\pi$ nearest","options":["4.93 atm","2.46 atm","0.20 atm","8.21 atm"],"answer_index":0,"explanation":"$\\pi = iCRT = 2 \\times 0.10 \\times 0.0821 \\times 300 = 4.93$ atm.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-261","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"The van’t Hoff factor i is the ratio of","options":["the observed colligative effect to the effect calculated for no ionisation","molarity to molality","$K_H$ to p","$K_b$ to $K_f$"],"answer_index":0,"explanation":"i = $\\Delta T_{\\mathrm{obs}} / \\Delta T_{\\mathrm{calc}}$ (and likewise for $\\pi$ or relative lowering).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-262","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"For a non-electrolyte that neither associates nor dissociates, i is","options":["1","0","2","0.5"],"answer_index":0,"explanation":"One formula unit still gives one particle, so the factor is unity.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-263","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Complete dissociation of K2SO4 in water gives i equal to","options":["3","2","1","4"],"answer_index":0,"explanation":"K2SO4 → 2 K⁺ + SO₄²⁻, three ions, so i = 3 when $\\alpha = 1$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-264","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Association of solute molecules makes the observed molar mass","options":["larger than the true formula mass","smaller than the true formula mass","unchanged","zero"],"answer_index":0,"explanation":"Fewer particles are present, so the colligative effect is smaller and $M_{\\mathrm{obs}} = M / i$ is larger (i < 1).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-265","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Dissociation of a solute makes the observed molar mass","options":["smaller than the true formula mass","larger than the true formula mass","infinite","equal to $K_b$"],"answer_index":0,"explanation":"More particles raise the colligative effect, so $M_{\\mathrm{obs}} = M / i$ falls below M.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-266","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Abnormal molar mass arises when","options":["the solute associates or dissociates","the solvent is merely wet","the temperature is 25 °C","$K_H$ is large"],"answer_index":0,"explanation":"Either process changes the particle count, so the molar mass inferred from a colligative law is abnormal.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-267","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"The relation connecting i, the number of particles n from one formula unit, and the degree of dissociation $\\alpha$ is","options":["$i = 1 + (n - 1)\\alpha$","$i = n\\alpha$","$i = 1 - n\\alpha$","$i = \\alpha / n$"],"answer_index":0,"explanation":"Each dissociated unit adds (n − 1) extra particles, so i − 1 = (n − 1)$\\alpha$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-268","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Benzoic acid in benzene often shows i less than 1 because it","options":["dimerises","ionises into four ions","evaporates completely","becomes a metal"],"answer_index":0,"explanation":"Hydrogen-bonded dimers reduce the particle count, so i < 1 and $M_{\\mathrm{obs}}$ is high.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-269","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"For Al2(SO4)3, complete dissociation would give i of","options":["5","3","2","4"],"answer_index":0,"explanation":"2 Al³⁺ + 3 SO₄²⁻ = five ions per formula unit.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-270","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"If i = 2 for a binary electrolyte AB, the degree of dissociation is","options":["1 (complete)","0.5","0","2"],"answer_index":0,"explanation":"i = 1 + (2 − 1)$\\alpha$ = 1 + $\\alpha$, so i = 2 means $\\alpha = 1$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-271","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Observed $\\Delta T_f$ divided by the $\\Delta T_f$ calculated with the theoretical molar mass equals","options":["i","$K_b$","$K_f$","$\\pi$"],"answer_index":0,"explanation":"That ratio is the definition of the van’t Hoff factor from freezing-point data.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-272","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"K4[Fe(CN)6] on complete ionisation yields particles numbering","options":["5","4","2","1"],"answer_index":0,"explanation":"Four K⁺ ions plus [Fe(CN)6]⁴⁻ give five particles, so i = 5 when fully split.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-273","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A binary electrolyte is 60% dissociated. The van’t Hoff factor is","options":["1.60","2.00","0.60","1.00"],"answer_index":0,"explanation":"i = 1 + (2 − 1)(0.60) = 1.60.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-274","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Acetic acid appears to have molar mass 120 g mol⁻¹ in benzene (true M = 60). Then i equals","options":["0.50","2.0","1.0","1.5"],"answer_index":0,"explanation":"i = $M_{\\mathrm{true}} / M_{\\mathrm{obs}} = 60/120 = 0.50$ (essentially complete dimerisation).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-275","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"BaCl2 is 80% dissociated. With n = 3, i is","options":["2.60","3.00","0.80","1.80"],"answer_index":0,"explanation":"i = 1 + (3 − 1)(0.80) = 2.60.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
